-- Add independently authored Spotify feature metadata; preserve existing 7 announcements.
-- This migration follows the initial feature catalogue and corrects beta country coverage.
INSERT INTO public.platform_feature_catalog
(platform, feature_id, title, category, announced_on, rollout_status, eligibility, market_codes, summary, matchapp_relevance, keyword_phrases, source_url, reviewed_on)
VALUES
('spotify', 'ai-persona-transparency', 'AI Persona badges for artist identity transparency', 'discovery', '2026-08-11'::date, 'rolling_out', 'The AI Persona badge is planned for selected artist profiles from September 2026 onward; visibility depends on the artist and Spotify rollout.', ARRAY[]::text[], 'Spotify introduced an AI Persona label intended to identify selected artist profiles using AI-generated identities, alongside broader artist verification and music-credit initiatives.', 'MatchApp Ai can encourage listeners to confirm artist identities and source information without labeling anyone as AI-generated on speculation.', ARRAY['Spotify AI Persona badge','Spotify AI generated artist label','Spotify artist verification','AI music transparency']::text[], 'https://newsroom.spotify.com/2026-08-11/ai-persona-badges-transparency/', '2026-10-21'::date),
('spotify', 'dj-brazilian-portuguese', 'DJ beta in Brazilian Portuguese and more languages', 'music', '2026-05-07'::date, 'available_in_eligible_markets', 'Spotify Premium listeners in Brazil and other supported markets; DJ remains a beta and availability can depend on account, country and device.', ARRAY['BR','PT','AT','FR','DE','IT','KR','CH']::text[], 'Spotify expanded its personalized DJ beta to Brazilian Portuguese, French, German and Italian, combining listening-history-based music choices with commentary and requested moods.', 'MatchApp Ai can guide listeners toward music moods and artists; it does not operate or impersonate Spotify''s native DJ.', ARRAY['Spotify DJ português brasileiro','DJ Spotify Brasil 2026','Spotify DJ Dani português','Spotify AI DJ Brazil','DJ personalizado Spotify']::text[], 'https://newsroom.spotify.com/2026-05-07/dj-chega-4-novos-idiomas/', '2026-10-21'::date),
('spotify', 'spotify-claude-integration', 'Spotify music and podcast recommendations in Claude', 'discovery', '2026-04-23'::date, 'available_in_eligible_markets', 'Available to eligible Spotify listeners using the Claude integration; account connection and Spotify Premium features vary by plan and region.', ARRAY[]::text[], 'Spotify launched an official integration in Claude, enabling connected listeners to request personalized music and podcast suggestions and move to Spotify for playback.', 'This integration belongs to Spotify and Claude, not MatchApp Ai; our recommendations and outbound discovery links remain independent.', ARRAY['Spotify Claude integration','Spotify in Claude','AI music assistant Spotify','podcast recommendations Claude']::text[], 'https://newsroom.spotify.com/2026-04-23/claude-integration/', '2026-10-21'::date),
('spotify', 'songdna-music-connections', 'SongDNA reveals collaborators, samples and cover versions', 'music', '2026-03-24'::date, 'available_in_eligible_markets', 'Spotify Premium mobile listeners globally on supported tracks; availability of credits and creative connections differs per song.', ARRAY[]::text[], 'Spotify''s SongDNA explores the writers, producers, collaborators, samples and cover recordings connected to a track within the Now Playing view.', 'MatchApp Ai can help users search for a genre, performer or related music idea but should not copy Spotify''s SongDNA network or credits without authorized sources.', ARRAY['Spotify SongDNA','Spotify song credits 2026','Spotify songs samples and covers','discover music collaborators']::text[], 'https://newsroom.spotify.com/2026-03-24/songdna-announcement-beta/', '2026-10-21'::date)
ON CONFLICT (platform, feature_id) DO UPDATE SET
  title = EXCLUDED.title, category = EXCLUDED.category,
  announced_on = EXCLUDED.announced_on, rollout_status = EXCLUDED.rollout_status,
  eligibility = EXCLUDED.eligibility, market_codes = EXCLUDED.market_codes,
  summary = EXCLUDED.summary, matchapp_relevance = EXCLUDED.matchapp_relevance,
  keyword_phrases = EXCLUDED.keyword_phrases, source_url = EXCLUDED.source_url,
  reviewed_on = EXCLUDED.reviewed_on, updated_at = now();

UPDATE public.platform_feature_catalog SET
 eligibility = 'Spotify Premium listeners aged 18 or older in the United States or New Zealand during the announced beta.',
 market_codes = ARRAY['US','NZ']::text[],
 reviewed_on = '2026-10-21'::date, updated_at = now()
WHERE platform = 'spotify' AND feature_id = 'taste-profile-beta';
